copied <- 0; missing <- character(0)
put <- function(src, dest_dir, rename = NULL) {
  if (!file.exists(src)) { missing <<- c(missing, src); return(invisible(FALSE)) }
  dst <- file.path(REPO, dest_dir, if (is.null(rename)) basename(src) else rename)
  file.copy(src, dst, overwrite = TRUE)
  copied <<- copied + 1; invisible(TRUE)
}

