# ---------------------------------------------------------------- 2b. BANNERS
# Stamps every mirrored script with a one-line header so it is unmistakable, even read out of
# context, that this file is a COPY and where the real working copy lives. Wired in here (not
# applied once by hand) so the banner survives every regeneration automatically, and re-stamps
# in place rather than duplicating if a banner from a prior run is already there. 29 Aug 2026,
# part of the live/exploratory reorg — see 00_LIVE_VS_EXPLORATORY.md.
banner_stamp <- function(rel_src, dest_dir) {
  dst <- file.path(REPO, dest_dir, basename(rel_src))
  if (!file.exists(dst)) return(invisible(FALSE))
  txt <- readLines(dst, warn = FALSE)
  banner <- sprintf("# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: %s", rel_src)
  if (length(txt) > 0 && startsWith(txt[1], "# COPY — generated by build_repo_mirror.R")) {
    txt[1] <- banner
  } else {
    txt <- c(banner, txt)
  }
  writeLines(txt, dst)
}
for (s in SCRIPTS) banner_stamp(s, "scripts")
