# ---------------------------------------------------------------- 2c. PRUNE STALE COPIES
# ⚠ file.copy(overwrite=TRUE) only ever ADDS or UPDATES — a script dropped from SCRIPTS/HELPERS
#   (e.g. an archived original) is never removed from a prior run's WKBD_repo/ output, and sits
#   there as an orphan indefinitely. Caught 29 Aug 2026 when scripts/02_great_officers.R was
#   archived but its stale mirror copy kept reappearing after every rebuild. Safe to prune: this
#   only ever deletes inside WKBD_repo/, which is 100% regenerated copies, never the working tree.
prune_stale <- function(dest_dir, expected_srcs) {
  expected <- basename(expected_srcs)
  present  <- list.files(file.path(REPO, dest_dir), pattern = "\\.R$")
  stale    <- setdiff(present, expected)
  for (f in stale) {
    file.remove(file.path(REPO, dest_dir, f))
    cat(sprintf("⚠ pruned stale mirror copy: %s/%s (no longer in SCRIPTS/HELPERS)\n", dest_dir, f))
  }
}
