# newest "Chapter Two vNN.docx" only. ⛔ Word lock files (~$...) are skipped.
# ⚠ BUG FOUND AND FIXED 14 Sep 2026: put()'s overwrite=TRUE only replaces a file with the SAME
#   destination name — since each version has a different "vNN" filename, every rebuild left the
#   previous run's older version sitting alongside the new one instead of replacing it. Found 17
#   accumulated versions (v24 through v72) never pruned. Now explicitly removes every other
#   "Chapter Two v*.docx" in the mirror before copying the current newest one in.
ch <- list.files(file.path(P, "chapters"), pattern = "^Chapter Two v[0-9]+\\.docx$", full.names = TRUE)
if (length(ch)) {
  v  <- as.integer(sub(".*v([0-9]+)\\.docx$", "\\1", ch))
  newest <- ch[which.max(v)]
  old_mirror_copies <- list.files(file.path(REPO, "manuscript"),
                                   pattern = "^Chapter Two v[0-9]+\\.docx$", full.names = TRUE)
  stale <- setdiff(old_mirror_copies, file.path(REPO, "manuscript", basename(newest)))
  for (f in stale) { file.remove(f); cat(sprintf("⚠ pruned stale manuscript version: %s\n", basename(f))) }
  put(newest, "manuscript")
  cat(sprintf("manuscript: %s\n", basename(newest)))
}
