prune_stale2 <- function(dest_dir, expected) {
  # only.files, not.dirs — a subfolder (e.g. tables/ch2_appendix/figures/) living inside a
  # pruned dest_dir is not a stale FILE and must not be passed to file.remove(). Caught 14 Sep
  # 2026 when ch2_appendix/figures/ (added same session) tripped this on its parent dir's prune.
  present <- list.files(file.path(REPO, dest_dir))
  present <- present[!file.info(file.path(REPO, dest_dir, present))$isdir]
  stale   <- setdiff(present, basename(expected))
  for (f in stale) {
    file.remove(file.path(REPO, dest_dir, f))
    cat(sprintf("⚠ pruned stale mirror copy: %s/%s\n", dest_dir, f))
  }
}
